// Golden positions on the Sample Keep (examples/sample-pack/maps/sample-keep), the 48 x 48 test bench map
// generated by tools/samples/sample_keep.py.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { prepare, canSee } from '../engine/sight/visibility.js';
import { prepareMove, path as route } from '../engine/movement/movement.js';
import { LightMap, LightCache, BRIGHT, DIM, DARK } from '../engine/light/light.js';
import { TerrainMap } from '../engine/terrain/terrain.js';
import { lightSpec } from '../rulesets/pf2e/light.js';

const DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'examples', 'sample-pack', 'maps', 'sample-keep');
const read = (f) => JSON.parse(fs.readFileSync(path.join(DIR, f), 'utf8'));
const map = read('map.json'), segs = read('walls.json').segs, terrain = read('terrain.json').areas, lighting = read('lighting.json');
const G = map.grid;
const sight = prepare(segs, {}, 'sight');
const opts = { rangeFt: 400, feetPerCell: 5 };

function lightNow(state = {}, sky = 'bright', extra = []) {
  const on = (l) => (state.lights && state.lights[l.id] ? state.lights[l.id].on : l.on !== false);
  const lights = lighting.lights.filter(on).map((l) => ({ ...l, ...lightSpec(l) })).concat(extra);
  return new LightMap(G, { base: map.base_light, sky, regions: lighting.regions, patches: new LightCache(G).patchesFor(lights, segs, state, JSON.stringify(state)) });
}

test('keep: the portcullis lets sight through but not feet', () => {
  assert.ok(canSee([24, 32.5], [24, 27.5], sight, opts));
  const pm = prepareMove(segs, {}, G);
  const r = route(pm, { x: 23, y: 31, size: 1 }, 23, 28);
  assert.ok(!r || r.feet > 15, 'no straight walk through the portcullis');
});

test('keep: pillars block sight across the hall', () => {
  assert.ok(!canSee([17.5, 17.2], [17.5, 21.5], sight, opts), 'pillar at (17, 19)');
  assert.ok(canSee([19.5, 17.2], [19.5, 21.5], sight, opts), 'between pillars');
});

test('keep: stained glass passes light but not sight', () => {
  assert.ok(!canSee([19, 4], [19, 8], sight, opts));
  const day = lightNow();
  assert.equal(day.at(19, 4), BRIGHT, 'outside is daylight');
});

test('keep: indoors is dark by day; the collapsed hall corner is open to the sky', () => {
  const day = lightNow();
  assert.equal(day.at(20, 22), DARK, 'great hall, away from the braziers');
  assert.equal(day.at(31.5, 16.5), BRIGHT, 'under the fallen roof');
  assert.equal(lightNow({}, 'dark').at(31.5, 16.5), DARK, 'at night');
});

test('keep: braziers light the hall; the gate torches start unlit and can be lit', () => {
  const day = lightNow();
  assert.equal(day.at(15.6, 27.6), BRIGHT);
  assert.equal(lightNow({}, 'dark').at(22.5, 31.5), DARK);
  assert.notEqual(lightNow({ lights: { 'gate-torch-w': { on: true } } }, 'dark').at(22.5, 31.5), DARK);
});

test('keep: fungus gives the cellar corner dim light', () => {
  assert.equal(lightNow().at(7.5, 27.5), DIM);
});

test('keep: terrain where the art draws it, and the flood starts off', () => {
  const t = new TerrainMap(terrain);
  assert.equal(t.at(33, 37)[0].kind, 'swim');
  assert.equal(t.at(36, 38)[0].kind, 'narrow', 'the bridge is not water');
  assert.equal(t.at(6, 15)[0].kind, 'hazardous');
  assert.deepEqual(t.at(7, 23), []);
  assert.equal(new TerrainMap(terrain, { terrain_on: ['cellar-flood'] }).at(7, 23)[0].kind, 'greater_difficult');
});
